CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;
CREATE TABLE IF NOT EXISTS public.restaurant_void_totp (restaurant_id uuid PRIMARY KEY REFERENCES public.restaurants(id) ON DELETE CASCADE, secret bytea NOT NULL, enabled boolean NOT NULL DEFAULT true, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.restaurant_void_totp FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.restaurant_void_totp TO service_role;
ALTER TABLE public.restaurant_void_totp ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS public.restaurant_void_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES public.restaurants(id) ON DELETE CASCADE, user_id uuid NOT NULL, bill_uid text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.restaurant_void_approvals FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.restaurant_void_approvals TO service_role;
ALTER TABLE public.restaurant_void_approvals ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public._void_totp_code(_secret bytea, _step bigint) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE msg bytea := decode(lpad(to_hex(_step), 16, '0'), 'hex'); digest bytea; offset_n integer; binary_n bigint; BEGIN digest := public.hmac(msg, _secret, 'sha1'); offset_n := get_byte(digest, 19) & 15; binary_n := ((get_byte(digest, offset_n) & 127)::bigint << 24) | ((get_byte(digest, offset_n + 1))::bigint << 16) | ((get_byte(digest, offset_n + 2))::bigint << 8) | (get_byte(digest, offset_n + 3))::bigint; RETURN lpad((binary_n % 1000000)::text, 6, '0'); END; $$;
REVOKE EXECUTE ON FUNCTION public._void_totp_code(bytea, bigint) FROM PUBLIC, anon, authenticated;
CREATE OR REPLACE FUNCTION public.setup_void_approval_code() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE rid uuid; secret_value bytea; BEGIN SELECT restaurant_id INTO rid FROM public.restaurant_members WHERE user_id = auth.uid() AND role IN ('owner','manager') ORDER BY restaurant_id LIMIT 1; IF rid IS NULL THEN RAISE EXCEPTION 'Owner or manager access required' USING ERRCODE='42501'; END IF; secret_value := public.gen_random_bytes(20); INSERT INTO public.restaurant_void_totp(restaurant_id, secret, enabled, created_by) VALUES (rid, secret_value, true, auth.uid()) ON CONFLICT (restaurant_id) DO UPDATE SET secret = EXCLUDED.secret, enabled = true, created_by = auth.uid(), created_at = now(); RETURN jsonb_build_object('enabled', true, 'message', 'Rotating approval code enabled'); END; $$;
REVOKE EXECUTE ON FUNCTION public.setup_void_approval_code() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.setup_void_approval_code() TO authenticated;
CREATE OR REPLACE FUNCTION public.get_void_approval_code() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE rid uuid; secret_value bytea; step_n bigint := floor(extract(epoch FROM clock_timestamp()) / 30)::bigint; BEGIN SELECT restaurant_id INTO rid FROM public.restaurant_members WHERE user_id = auth.uid() AND role IN ('owner','manager') ORDER BY restaurant_id LIMIT 1; IF rid IS NULL THEN RAISE EXCEPTION 'Owner or manager access required' USING ERRCODE='42501'; END IF; SELECT secret INTO secret_value FROM public.restaurant_void_totp WHERE restaurant_id = rid AND enabled; IF secret_value IS NULL THEN RAISE EXCEPTION 'Rotating approval code is not configured'; END IF; RETURN jsonb_build_object('code', public._void_totp_code(secret_value, step_n), 'expires_at', (step_n + 1) * 30); END; $$;
REVOKE EXECUTE ON FUNCTION public.get_void_approval_code() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_void_approval_code() TO authenticated;
CREATE OR REPLACE FUNCTION public.verify_void_approval_code(_restaurant_id uuid, _bill_uid text, _code text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$ DECLARE secret_value bytea; step_n bigint := floor(extract(epoch FROM clock_timestamp()) / 30)::bigint; valid_code boolean := false; BEGIN IF auth.uid() IS NULL OR _bill_uid IS NULL OR length(_bill_uid) > 128 OR _code IS NULL OR _code !~ '^[0-9]{6}$' THEN RETURN false; END IF; IF NOT public.is_member(_restaurant_id, auth.uid()) THEN RAISE EXCEPTION 'Restaurant membership required' USING ERRCODE='42501'; END IF; SELECT secret INTO secret_value FROM public.restaurant_void_totp WHERE restaurant_id = _restaurant_id AND enabled; IF secret_value IS NULL THEN RETURN false; END IF; valid_code := _code = public._void_totp_code(secret_value, step_n) OR _code = public._void_totp_code(secret_value, step_n - 1) OR _code = public._void_totp_code(secret_value, step_n + 1); IF NOT valid_code THEN RETURN false; END IF; INSERT INTO public.restaurant_void_approvals(restaurant_id, user_id, bill_uid, expires_at) VALUES (_restaurant_id, auth.uid(), _bill_uid, clock_timestamp() + interval '2 minutes'); RETURN true; END; $$;
REVOKE EXECUTE ON FUNCTION public.verify_void_approval_code(uuid, text, text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.verify_void_approval_code(uuid, text, text) TO authenticated;